def transform(grid):
    """Keep the marked panel and recolor its minority pattern color to 3."""
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    # A full uniform row/column distinct from the exterior background separates panels.
    separators = []
    for r, row in enumerate(grid):
        if len(set(row)) == 1 and row[0] != bg:
            separators.append(("row", r, row[0]))
    for c in range(w):
        vals = [grid[r][c] for r in range(h)]
        if len(set(vals)) == 1 and vals[0] != bg:
            separators.append(("col", c, vals[0]))
    axis, idx, _ = separators[0]
    if axis == "row":
        panel = [row[:] for row in grid[idx + 1:]]
    else:
        panel = [row[idx + 1:] for row in grid]
    counts = Counter(v for row in panel for v in row)
    # In the selected patterned panel, the most frequent value is its ground color.
    ground = counts.most_common(1)[0][0]
    return [[v if v == ground else 3 for v in row] for row in panel]


